  function randomStealableInventoryEntry(){const all=inventoryCounts().filter(e=>!isGoldItem(e.meta.raw));return all.length?all[Math.floor(Math.random()*all.length)]:null;}
  function normalizeCombatItemName(value=''){return cleanText(value).toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();}
