  const COMBAT_BEAT_PRIORITY={routine:10,significant:50,spotlight:100};
  const COMBAT_BEAT_SURFACE_PRIORITY={silent:0,inline:1,moment:2};
  function narrativeCompose({family='generic',templates=[],seed='',context={},finalize=null}={}){
    const source=[];
    for(const entry of (templates||[])){
      try{const value=typeof entry==='function'?entry(context):entry,text=cleanText(value);if(text)source.push(text);}catch(err){console.warn('[Samsara Narrativa] template ignorado.',err);}
    }
    if(!source.length)return'';
    const variants=[];
    for(let i=0;i<source.length;i++){
      let value=source[i];
      try{value=narrativeReactionVariation(value,`${seed}|${i}`,family)||value;}catch(err){console.warn('[Samsara Narrativa] variação reduzida.',err);}
      if(typeof finalize==='function')try{value=cleanText(finalize(value,{index:i,family,seed,context}))||value;}catch(err){console.warn('[Samsara Narrativa] acabamento reduzido.',err);}
      value=cleanText(value);if(value)variants.push(value);
    }
    if(!variants.length)return source[0]||'';
    return stableSeedPick(variants,seed||`${family}|${appState.sectionId}`)||variants[0];
  }
  const SYSTEM_NARRATIVE_PRIORITY={routine:10,significant:50,spotlight:100};
  let systemNarrativeQueue=[],systemNarrativeBusy=false,systemNarrativeCycle=null;
  function ensureSystemNarrativeState(p=appState.player){
    if(!p)return null;
    if(!p.systemNarrativeMemory||typeof p.systemNarrativeMemory!=='object'||Array.isArray(p.systemNarrativeMemory)){
      p.systemNarrativeMemory={};
      for(const raw of p.items||[]){const meta=itemMeta(raw);if(meta?.key)p.systemNarrativeMemory[`item:${meta.key}`]=1;}
    }
    if(!Number.isFinite(Number(p.systemNarrativeSequence)))p.systemNarrativeSequence=0;
    return p;
  }
  function systemNarrativeSeen(key=''){const p=ensureSystemNarrativeState();return !!(key&&p?.systemNarrativeMemory?.[key]);}
  function rememberSystemNarrative(key=''){const p=ensureSystemNarrativeState();if(!p||!key)return;p.systemNarrativeMemory[key]=(Number(p.systemNarrativeMemory[key])||0)+1;}
  function nextSystemNarrativeSeed(kind='system',extra=''){const p=ensureSystemNarrativeState(),seq=p?(p.systemNarrativeSequence=Number(p.systemNarrativeSequence||0)+1):Date.now();return `${ensureBookIdentity(appState.book||{})}|${appState.sectionId}|${kind}|${extra}|${seq}`;}
  function systemNarrativeMoment(spec={}){const importance=['routine','significant','spotlight'].includes(spec.importance)?spec.importance:'significant';return {kind:cleanText(spec.kind||'system')||'system',importance,title:cleanText(spec.title||''),headline:cleanText(spec.headline||''),detail:cleanText(spec.detail||''),icon:cleanText(spec.icon||''),memoryKey:cleanText(spec.memoryKey||''),repeat:spec.repeat==='once'?'once':'always',data:spec.data&&typeof spec.data==='object'?{...spec.data}:{},order:Number(spec.order)||0};}
  function systemNarrativeItemEligible(meta){return !!(meta?.name&&!isProvisionName(meta.raw||meta.name)&&!isGoldItem(meta.raw||meta.name));}
  function systemItemNarrativeSpec(meta={}){const cat=categoryKey(meta.category||''),name=cleanText(meta.name||'o achado')||'o achado',lib={arma:[`Você testa o peso de ${name} nas mãos e entende que ele pode mudar a maneira como enfrenta o próximo perigo.`,`O equilíbrio de ${name} revela seu propósito assim que você o examina.`],armadura:[`Você ajusta ${name} ao corpo e percebe onde ele pode fazer diferença quando o próximo golpe vier.`,`Ao examinar ${name}, você reconhece uma proteção capaz de acompanhar a jornada.`],livro:[`As páginas de ${name} carregam algo que merece ser levado adiante.`,`Você folheia ${name} o bastante para perceber que há conhecimento esperando ali.`],feitiço:[`Uma nova possibilidade arcana se abre quando ${name} chega até você.`,`Você reconhece em ${name} uma forma de alterar aquilo que parecia inevitável.`],poções:[`O conteúdo de ${name} promete alguma mudança guardada para o momento certo.`,`Você observa ${name} e guarda o frasco sabendo que seu efeito pode importar mais adiante.`]};return {family:'system-item',templates:lib[cat]||[`Você examina ${name} antes de incorporá-lo ao que leva consigo.`,`O achado encontra lugar entre seus recursos e passa a fazer parte da jornada.`]};}
  function systemStateNarrativeSpec(kind='state-added',name=''){const key=stateKey(name),added=kind==='state-added',specific={envenenado:added?[`Um gosto metálico toma sua boca. Algo nocivo já circula por dentro.`,`O corpo reconhece o veneno antes que você consiga ignorar seus sinais.`]:[`O gosto metálico desaparece e seu corpo finalmente começa a responder com clareza.`,`A presença do veneno recua até deixar de comandar suas reações.`],apaixonado:added?[`Sua atenção passa a gravitar em torno de um sentimento difícil de afastar.`,`Uma afeição intensa ocupa espaço demais entre pensamento e impulso.`]:[`A intensidade emocional cede e sua atenção volta a pertencer inteiramente a você.`,`O sentimento perde a força que vinha desviando suas decisões.`],algemado:added?[`O metal fecha seus movimentos e transforma cada gesto em uma negociação com a contenção.`,`As algemas limitam imediatamente o alcance de seus movimentos.`]:[`A pressão do metal desaparece e seus movimentos recuperam amplitude.`,`As algemas deixam de determinar até onde suas mãos podem ir.`],preso:added?[`A contenção fecha suas possibilidades de movimento e obriga você a agir dentro de pouco espaço.`,`Você percebe o corpo limitado por algo que impede uma movimentação livre.`]:[`A contenção cede e o espaço ao seu redor volta a ser utilizável.`,`Você recupera liberdade para mover o corpo sem a antiga restrição.`],amarrado:added?[`As amarras apertam o corpo e transformam movimentos simples em esforço.`,`Cordas ou laços prendem seus movimentos antes que você consiga encontrar folga.`]:[`As amarras cedem e o corpo recupera liberdade.`,`Você se livra da tensão que vinha prendendo seus movimentos.`],paralisado:added?[`O comando chega aos músculos e encontra silêncio. Seu corpo demora a responder.`,`Uma rigidez súbita percorre o corpo e interrompe o movimento.`]:[`O corpo volta a responder, primeiro aos poucos, depois por inteiro.`,`A rigidez desaparece e os movimentos retornam.`],congelado:added?[`O frio prende músculos e articulações como se o corpo estivesse sendo tomado por dentro.`,`Uma rigidez gelada invade seus movimentos e reduz cada reação.`]:[`O frio perde domínio sobre o corpo e as articulações voltam a obedecer.`,`A rigidez gelada cede e seus movimentos retornam.`],imobilizado:added?[`Seus movimentos se fecham até quase desaparecer.`,`A mobilidade some e obriga você a lutar contra a própria contenção.`]:[`Você recupera o controle do corpo e volta a ocupar espaço.`,`A imobilidade cede e o movimento retorna.`],agourado:added?[`Uma sensação ruim se instala e permanece perto demais para ser descartada como acaso.`,`O ambiente parece ganhar um peso estranho, como se algo desfavorável acompanhasse seus passos.`]:[`A pressão invisível se desfaz e o mundo parece recuperar proporções normais.`,`A sensação de mau presságio finalmente perde força.`],enlouquecido:added?[`A realidade perde uma parte de seus contornos e pensamentos antes separados começam a se tocar.`,`Alguma coisa muda na forma como sua mente organiza o que está diante de você.`]:[`Os contornos do mundo voltam a encontrar lugares mais estáveis dentro de sua mente.`,`A percepção recupera parte da ordem que havia perdido.`]};return {family:'system-state',templates:specific[key]||(added?[`Algo em sua condição muda e passa a interferir na maneira como você atravessa a cena.`,`Você percebe uma alteração persistente antes mesmo de medir todas as suas consequências.`]:[`A influência que vinha acompanhando você finalmente cede.`,`Uma condição que limitava sua jornada perde força e desaparece.`])};}
  function systemKnowledgeNarrativeSpec(result={}){if(result.kind==='collapse')return {family:'system-knowledge',templates:[`Referências, relações e certezas se desfazem ao mesmo tempo. O que antes estava organizado deixa apenas lacunas.`,`Sua rede de conhecimentos perde coesão de uma vez, como páginas arrancadas de muitos livros ao mesmo tempo.`]};if(result.kind==='amnesia')return {family:'system-knowledge',templates:[`As lembranças se embaralham, mas conexões inesperadas surgem entre elas por algum tempo.`,`A memória perde ordem e, justamente por isso, aproxima ideias que antes permaneciam separadas.`]};if(result.kind==='limit')return {family:'system-knowledge',templates:[`Sua mente tenta acomodar a nova informação, mas o que já carrega exige espaço demais.`,`O conhecimento encontra uma mente já ocupada por muitas referências e deixa de se fixar.`]};if(result.kind==='gain'&&Number(result.value)>1)return {family:'system-knowledge',templates:[`O que você já sabia sobre ${result.name} ganha profundidade e novas conexões.`,`Uma compreensão anterior de ${result.name} se amplia e passa a oferecer mais caminhos.`]};return {family:'system-knowledge',templates:[`Uma nova compreensão de ${result.name} encontra lugar entre aquilo que você sabe.`,`O que acabou de aprender sobre ${result.name} se organiza como conhecimento que pode ser usado depois.`]};}
  function systemTestNarrative({test='',success=false,critical=null,knowledgeName='',knowledgeUsesLuck=false}={}){const kind=normalizeTestToken(test),seed=nextSystemNarrativeSeed('test',`${kind}|${success?'success':'failure'}|${critical||''}|${knowledgeName}`);let spec;if(kind==='APTIDÃO'){if(critical==='success')spec={family:'test-skill-critical',templates:[`Tudo se encaixa no instante certo. Movimento, leitura da situação e decisão viram uma única ação precisa.`,`Você encontra uma execução rara: o desafio cede antes que sua confiança tenha tempo de vacilar.`]};else if(critical==='failure')spec={family:'test-skill-critical',templates:[`O movimento começa errado e arrasta o restante da tentativa junto. Por alguns instantes, até o que costuma ser natural parece difícil.`,`A execução se desfaz de maneira tão completa que sua confiança corporal acompanha a falha.`]};else spec=success?{family:'test-skill',templates:[`Você encontra a medida certa entre intenção e execução.`,`A situação exige precisão, e seu corpo responde a tempo.`]}:{family:'test-skill',templates:[`A execução fica aquém do que a situação exigia.`,`Você tenta impor sua capacidade à situação, mas o momento escapa.`]};}else if(critical==='success')spec={family:'test-generic-critical',templates:[`O resultado se encaixa com precisão excepcional e transforma a tentativa em um sucesso raro.`,`A margem perfeita aparece no momento exato e leva a tentativa ao melhor desfecho possível.`]};else if(critical==='failure')spec={family:'test-generic-critical',templates:[`A tentativa se desfaz no extremo oposto do que você buscava, com uma falha impossível de disfarçar.`,`Tudo se desalinha ao mesmo tempo e a tentativa termina em um fracasso excepcional.`]};else if(kind==='FORTUNA')spec=success?{family:'test-luck',templates:[`O acaso abre exatamente a margem de que você precisava.`,`Entre possibilidades ruins, uma brecha improvável se oferece a você.`]}:{family:'test-luck',templates:[`O acaso segue outro caminho e deixa você com as consequências da tentativa.`,`A margem que poderia favorecer você simplesmente passa adiante.`]};else if(kind==='SANIDADE')spec=success?{family:'test-sanity',templates:[`Você mantém a mente firme o bastante para atravessar o esforço sem perder o fio da intenção.`,`Pensamento e vontade permanecem alinhados enquanto a pressão tenta dispersá-los.`]}:{family:'test-sanity',templates:[`A pressão encontra espaço dentro de você e rompe parte da concentração necessária.`,`Sua mente tenta sustentar o esforço, mas a clareza se desfaz antes do fim.`]};else if(kind==='SABER'&&knowledgeUsesLuck)spec=success?{family:'test-knowledge-luck',templates:[`Sem domínio de ${knowledgeName}, você se apoia em indícios, instinto e coincidência — e encontra o caminho.`,`Você conhece pouco de ${knowledgeName}, mas uma associação improvável conduz à resposta certa.`]}:{family:'test-knowledge-luck',templates:[`Sem domínio de ${knowledgeName}, os indícios deixam lacunas demais para uma conclusão segura.`,`Você tenta compensar a falta de ${knowledgeName} com intuição, mas a resposta continua fora de alcance.`]};else if(kind==='SABER')spec=success?{family:'test-knowledge',templates:[`${knowledgeName} oferece exatamente a referência que faltava para compreender a situação.`,`O que você aprendeu sobre ${knowledgeName} encontra uma aplicação clara neste momento.`]}:{family:'test-knowledge',templates:[`Você procura em ${knowledgeName} uma referência útil, mas a conexão certa escapa.`,`O conhecimento de ${knowledgeName} está presente, embora desta vez ele deixe uma lacuna importante.`]};else spec=success?{family:'test-generic',templates:[`A tentativa encontra o resultado que você buscava.`]}:{family:'test-generic',templates:[`A tentativa termina antes de alcançar o resultado desejado.`]};return narrativeCompose({...spec,seed});}

  function systemExceptionalNarrative({event='',actor='HERO',target='',weapon='',spell='',epaResult=null,consequence=''}={}){const seed=nextSystemNarrativeSeed('exceptional',`${event}|${actor}|${target}|${weapon}|${spell}|${epaResult??''}|${consequence}`),foe=cleanText(target)||'o adversário',item=cleanText(weapon)||'o golpe',magic=cleanText(spell)||'a magia';let spec={family:'exceptional',templates:[`O instante muda de direção antes que alguém consiga recuperar o ritmo.`]};if(event==='POWERFUL_BLOW_HERO')spec={family:'combat-powerful-blow',templates:[`O ataque atravessa a guarda de ${foe} por inteiro. O impacto decide o confronto naquele instante.`,`${item} encontra uma abertura absoluta. ${foe} cede antes de conseguir recompor a defesa.`]};else if(event==='POWERFUL_BLOW_ENEMY')spec={family:'combat-powerful-blow',templates:[`${foe} atravessa sua guarda com um golpe absoluto. O impacto encerra sua resistência.`,`A defesa se abre por um único instante, e ${foe} transforma a abertura em um golpe devastador.`]};else if(event==='POWERFUL_BLOW_CLASH')spec={family:'combat-powerful-clash',templates:[`Os dois ataques chegam com força total. ${consequence||'O choque cobra seu preço nos dois lados.'}`,`Os golpes colidem no mesmo instante. ${consequence||'Armas e corpos recebem o impacto.'}`]};else if(event==='FUMBLE_HERO')spec={family:'combat-fumble',templates:[`Seu movimento entra cedo demais. A abertura muda de lado antes que você consiga corrigir a execução.`,`O ataque perde alinhamento no momento decisivo e entrega a iniciativa ao adversário.`]};else if(event==='FUMBLE_ENEMY')spec={family:'combat-fumble',templates:[`${foe} perde o eixo do ataque por um instante. A falha abre espaço para sua reação.`,`O movimento de ${foe} se desfaz na execução e transforma pressão em oportunidade.`]};else if(event==='FUMBLE_BOTH')spec={family:'combat-fumble',templates:[`Os dois movimentos saem do eixo ao mesmo tempo. A troca termina em desordem, sem vantagem limpa para qualquer lado.`,`A ofensiva de ambos se desfaz no mesmo instante, e o confronto precisa ser retomado do zero.`]};else if(event==='MAGIC_CRITICAL_SUCCESS')spec={family:'magic-critical',templates:[`${magic} se forma com precisão rara. A energia encontra o caminho mais curto e exige menos esforço.`,`A conjuração se fecha com perfeição. ${magic} responde com uma eficiência incomum.`]};else if(event==='EPA')spec={family:'magic-epa',templates:[`A estrutura de ${magic} se rompe no último instante. A magia escapa do desenho original e produz um efeito impossível de conter.`,`O feitiço dobra sobre si mesmo e descarrega magia bruta fora do padrão esperado.`]};return narrativeCompose({...spec,seed});}
  function recordExceptionalEvent(event,data={}){const p=ensurePlayerStats();if(!p)return null;if(!Array.isArray(p.exceptionalEvents))p.exceptionalEvents=[];const rec={event,sectionId:appState.sectionId||'',round:Number(data.round)||0,at:Date.now(),...deepClone(data)};p.exceptionalEvents.push(rec);if(p.exceptionalEvents.length>80)p.exceptionalEvents.shift();return rec;}
  async function presentExceptionalNarrative(spec={}){const text=systemExceptionalNarrative(spec),event=cleanText(spec.event||'EXCEPTIONAL');recordExceptionalEvent(event,{actor:spec.actor||'',target:spec.target||'',weapon:spec.weapon||'',spell:spec.spell||'',epaResult:spec.epaResult??null,consequence:spec.consequence||'',round:spec.round||appState.combat?.round||0});if(!text)return'';await showRewardMoment({kind:'special',title:spec.title||'EVENTO EXCEPCIONAL',headline:spec.headline||event.replaceAll('_',' '),detail:text,icon:spec.icon||'✦',image:spec.image||''});return text;}

  function systemNarrativeText(moment){const m=systemNarrativeMoment(moment),d=m.data||{};if(m.detail)return m.detail;let spec={family:m.kind,templates:[]};if(m.kind==='item-discovered')spec=systemItemNarrativeSpec(d.meta||{name:d.name,category:d.category,raw:d.raw});else if(m.kind==='items-discovered')spec={family:'system-item',templates:[`Você recolhe os achados e percebe que mais de uma nova possibilidade passa a acompanhar a jornada.`,`O conjunto de descobertas amplia aquilo que você poderá colocar em jogo daqui em diante.`]};else if(m.kind==='state-added'||m.kind==='state-removed')spec=systemStateNarrativeSpec(m.kind,d.name||m.headline);else if(m.kind==='states-cleared')spec={family:'system-state',templates:[`As condições que vinham alterando sua jornada cedem de uma vez, e seu corpo recupera um estado mais estável.`,`Uma série de influências perde força ao mesmo tempo e deixa você novamente sem aquelas restrições.`]};else if(m.kind.startsWith('knowledge-'))spec=systemKnowledgeNarrativeSpec(d.result||{});return narrativeCompose({...spec,seed:nextSystemNarrativeSeed(m.kind,m.memoryKey||m.headline)});}
  function systemNarrativeSurfaceBusy(){const reward=el('rewardOverlay');return !!((reward&&!reward.classList.contains('hidden'))||diceRollSurfaceVisible()||appState.pageTurning||appState.deathFlowActive||appState.deathPresentationPending);}
  async function runSystemNarrativeQueue(){if(systemNarrativeBusy||!systemNarrativeQueue.length)return;systemNarrativeBusy=true;try{while(systemNarrativeQueue.length){while(systemNarrativeSurfaceBusy())await new Promise(r=>setTimeout(r,120));const moment=systemNarrativeQueue.shift();if(!moment||appState.editor||!appState.adventureStarted)continue;const detail=systemNarrativeText(moment);if(!detail)continue;await showRewardMoment({kind:'special',title:moment.title||'ALGO MUDOU',headline:moment.headline||'',detail,icon:moment.icon||'✦',italicDetail:true});}}finally{systemNarrativeBusy=false;if(systemNarrativeQueue.length)setTimeout(runSystemNarrativeQueue,60);}}
  function queueSystemNarrativeMoment(spec={}){const moment=systemNarrativeMoment(spec);if(appState.editor||!appState.adventureStarted)return null;if(moment.repeat==='once'&&moment.memoryKey){if(systemNarrativeSeen(moment.memoryKey))return null;rememberSystemNarrative(moment.memoryKey);}if(combatInProgress()&&(moment.kind==='state-added'||moment.kind==='state-removed'||moment.kind==='states-cleared'))return null;systemNarrativeQueue.push(moment);setTimeout(runSystemNarrativeQueue,30);return moment;}
  function beginSystemNarrativeCycle(label=''){if(systemNarrativeCycle)return false;systemNarrativeCycle={label,candidates:[],order:0};return true;}
  function offerSystemNarrativeMoment(spec={}){const moment=systemNarrativeMoment(spec);if(appState.editor||!appState.adventureStarted)return null;if(moment.repeat==='once'&&moment.memoryKey){if(systemNarrativeSeen(moment.memoryKey))return null;rememberSystemNarrative(moment.memoryKey);}if(combatInProgress()&&(moment.kind==='state-added'||moment.kind==='state-removed'||moment.kind==='states-cleared'))return null;if(!systemNarrativeCycle)return queueSystemNarrativeMoment({...moment,repeat:'always',memoryKey:''});moment.order=++systemNarrativeCycle.order;systemNarrativeCycle.candidates.push(moment);return moment;}
  function commitSystemNarrativeCycle(){const cycle=systemNarrativeCycle;systemNarrativeCycle=null;if(!cycle?.candidates?.length)return null;const candidates=[...cycle.candidates].sort((a,b)=>(SYSTEM_NARRATIVE_PRIORITY[b.importance]||0)-(SYSTEM_NARRATIVE_PRIORITY[a.importance]||0)||a.order-b.order),best=candidates[0],sameItems=candidates.filter(x=>x.kind==='item-discovered'&&x.importance===best.importance);if(best.kind==='item-discovered'&&sameItems.length>1){const names=sameItems.map(x=>x.data?.name||x.headline).filter(Boolean);return queueSystemNarrativeMoment({kind:'items-discovered',importance:best.importance,title:'DESCOBERTAS',headline:names.join(' · '),icon:'🎒'});}return queueSystemNarrativeMoment({...best,repeat:'always',memoryKey:''});}
  function noteSystemItemDiscovery(meta,source='section'){if(!systemNarrativeItemEligible(meta))return null;return offerSystemNarrativeMoment({kind:'item-discovered',importance:'significant',title:'DESCOBERTA',headline:cleanText(meta.name).toUpperCase(),icon:categoryKey(meta.category)==='livro'?'📖':categoryKey(meta.category)==='feitiço'?'🔮':categoryKey(meta.category)==='arma'?'⚔️':categoryKey(meta.category)==='armadura'?'🛡️':'🎒',memoryKey:`item:${meta.key}`,repeat:'once',data:{name:meta.name,category:meta.category,raw:meta.raw,meta:{name:meta.name,category:meta.category,raw:meta.raw,key:meta.key},source}});}
  function noteSystemKnowledge(result,source='section'){if(!result||result.kind==='invalid')return null;const headline=result.kind==='gain'?String(result.name||'Perícia').toUpperCase():result.kind==='collapse'?'COLAPSO MENTAL':result.kind==='amnesia'?'AMNÉSIA':'MENTE SATURADA',importance=(result.kind==='gain'||result.kind==='collapse')?'spotlight':'significant';return offerSystemNarrativeMoment({kind:`knowledge-${result.kind}`,importance,title:result.kind==='gain'?'PERÍCIA DESCOBERTA':'PERÍCIAS',headline,icon:'🧠',data:{result:{...result},source}});}
  function noteSystemState(kind,name,{hidden=false,source='section'}={}){if(hidden||!cleanText(name))return null;return offerSystemNarrativeMoment({kind,importance:'significant',title:kind==='state-added'?'SUA CONDIÇÃO MUDOU':'CONDIÇÃO SUPERADA',headline:cleanText(name).toUpperCase(),icon:kind==='state-added'?'◈':'◇',data:{name:cleanStateName(name),source}});}

  function combatLifeBand(current,maximum){
    const cur=Math.max(0,Number(current)||0),max=Math.max(1,Number(maximum)||1),ratio=cur/max;
    if(cur<=0)return'dead';if(ratio<=.25)return'critical';if(ratio<=.55)return'wounded';return'healthy';
  }
  function combatBeat(spec={}){
    const importance=['routine','significant','spotlight'].includes(spec.importance)?spec.importance:'routine',
      surface=['silent','inline','moment'].includes(spec.surface)?spec.surface:(importance==='spotlight'?'moment':importance==='significant'?'inline':'silent');
    return {kind:cleanText(spec.kind||'routine')||'routine',importance,surface,memoryKey:cleanText(spec.memoryKey||''),repeat:spec.repeat==='once'?'once':'always',text:cleanText(spec.text||''),title:cleanText(spec.title||''),headline:cleanText(spec.headline||''),data:spec.data&&typeof spec.data==='object'?{...spec.data}:{},order:Number(spec.order)||0};
  }
  function combatBeatSeen(c,key=''){return !!(key&&c?.narrativeMemory?.[key]);}
  function rememberCombatBeat(c,key=''){if(!c||!key)return;if(!c.narrativeMemory||typeof c.narrativeMemory!=='object')c.narrativeMemory={};c.narrativeMemory[key]=(Number(c.narrativeMemory[key])||0)+1;}
