  async function executeCombatUiAction(index,action){
    const c=setActiveCombat(index);if(!c||c.won||c.mercyPending||!appState.player||appState.player.stamina<=0)return;
    recoverStaleCombatUiAction(c);
    if(c.uiActionBusy)return;
    if(action==='dodge'&&!canUseCombatAction(c,'dodge'))return;
    if(action==='luck'&&!canUseCombatAction(c,'luck'))return;
    if(action==='attack'&&c.started&&!canUseCombatAction(c,'attack'))return;
    if(action==='attack'&&!c.started)stopCombatTensionAudio();
    c.uiActionBusy=true;
    const actionMode=actionCombatEnabled();
    try{
      if(actionMode&&['talk','dodge','luck'].includes(action))prepareActionCombatSideAction(c);
      if(action==='attack'){
        if(quickCombatEnabled()){await startQuickCombat(c);return;}
        if(actionMode){await startActionCombat(c);return;}
        await startStrategicCombat(c);return;
      }
      if(action==='dodge'){
        if(!c.started)return;
        await dodgeCombat(c);return;
      }
      if(action==='luck'){
        if(!c.pendingLuck||appState.player.luck<=0)return;
        await useCombatLuck(c);return;
      }
      if(action==='talk'){
        if(!c.started)markCombatEngagement(c,'HERO');
        await attemptCombatConversation(c);return;
      }
    }catch(err){console.error(`Falha na ação de combate: ${action}`,err);if(action==='dodge')c.dodgeUsedRound=null;if(action==='luck')c.luckUsedRound=null;}
    finally{
      c.uiActionBusy=false;
      if(actionMode&&actionCombatAttackEligible(c))scheduleActionCombatResume(c);
      renderAll();
    }
  }

