    if(name==='bola de fogo'){const r=await dramaticRoll({title:'Bola de Fogo',combatDuel:combatDuelMeta(c),lead:`Role 1d6 para definir o dano causado em ${c.name}.`,diceCount:1,evaluate:x=>({total:x[0],equation:`${x[0]} = ${x[0]} de dano`,headline:'FOGO ARCANO',detail:`${c.name} perde ${x[0]} VIDA.`,damage:x[0]})});if(r){const dealt=await applyOpponentDamageDefenses(c,r.outcome.damage,{roundLoss:false});if(dealt){queueFx('hitEnemy','IMPACTO MÁGICO',`${dealt} de dano em ${c.name}`);await triggerEncounterEvents('FIRST_HERO_DAMAGE',{combat:c});}}}
