  function markerSearchKey(value=''){return String(value||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLocaleLowerCase('pt-BR').trim();}
  function markerOptionData(option){return typeof option==='string'?{marker:option,desc:''}:option;}
  function markerMatches(option,query,context=''){if(!query)return true;const data=markerOptionData(option),hay=markerSearchKey(`${context} ${data.marker||''} ${data.desc||''}`);return hay.includes(markerSearchKey(query));}
