  function ensureEditorCatalog(book=appState.book){if(!book)return {items:[],states:[]};if(!Array.isArray(book.editorCustomItems))book.editorCustomItems=[];if(!Array.isArray(book.editorCustomStates))book.editorCustomStates=[];return {items:book.editorCustomItems,states:book.editorCustomStates};}
  function editorItemCategory(meta){const key=categoryKey(meta?.category||'');if(key==='materiais')return EDITOR_ITEM_CATEGORIES[1];if(key==='poções')return EDITOR_ITEM_CATEGORIES[2];if(key==='prazer')return EDITOR_ITEM_CATEGORIES[3];if(key==='arma')return EDITOR_ITEM_CATEGORIES[4];if(key==='armadura')return EDITOR_ITEM_CATEGORIES[5];if(key==='livro')return EDITOR_ITEM_CATEGORIES[6];if(key==='documento')return EDITOR_ITEM_CATEGORIES[7];if(key==='feitiço')return EDITOR_ITEM_CATEGORIES[8];return EDITOR_ITEM_CATEGORIES[0];}
