  function standardInsertItemKeys(){const set=new Set(),menus=['items','materials','potions','pleasure','weapons','armor','knowledge','documents','magic'];for(const key of menus)for(const option of MARKER_MENUS[key]||[]){const raw=markerItemRaw(option);if(raw)set.add(itemMeta(raw).key);}return set;}
  function discoveredEditorialItems(){
    const found=new Map(),book=appState.book,catalog=ensureEditorCatalog(book),remember=(raw,price=null,session=false)=>{const meta=itemMeta(raw);if(!meta?.name||isGoldItem(meta.raw)||isProvisionName(meta.raw))return;const key=meta.key,old=found.get(key),p=Number.isFinite(Number(price))&&Number(price)>0?Math.max(1,Math.round(Number(price))):null;if(!old)found.set(key,{raw:meta.raw,name:meta.name,category:meta.category,price:p,session});else{if(old.price==null&&p!=null)old.price=p;if(session){old.session=true;old.raw=meta.raw;old.name=meta.name;old.category=meta.category;}}};
    for(const entry of catalog.items)remember(entry.raw,entry.price,true);
    for(const id of book?.order||[]){const sec=book.sections?.[id];if(!sec)continue;for(const m of sec.mods||[])if(m.kind==='item')remember(m.item);for(const b of sec.books||[])remember(b.item);if(sec.treasure?.mode==='fixed')remember(sec.treasure.reward.item);for(const tr of sec.trades||[]){remember(tr.from.item);remember(tr.to.item);}for(const sale of sec.commerce||[])remember(sale.item,sale.price);for(const tempo of sec.tempos||[])for(const action of tempo.actions||[]){const im=String(action).match(/^\{\+\s*(.+)\}$/s);if(im&&!/^\d+\s+(?:APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)$/i.test(im[1].trim()))remember(parseItemModSpec(im[1].trim()).item);}}
    return [...found.values()];
  }
  function customEditorialItems(){const built=standardInsertItemKeys();return discoveredEditorialItems().filter(x=>!built.has(itemMeta(x.raw).key));}
  function discoveredEditorialStates(){
    const map=new Map(),book=appState.book,catalog=ensureEditorCatalog(book),remember=(name,{hidden=false,remove=false,session=false,duration=null}={})=>{name=cleanStateName(name);if(!name)return;const key=name.toLocaleLowerCase('pt-BR'),old=map.get(key);if(!old||session)map.set(key,{name,hidden:!!hidden,remove:!!remove,session:!!session,duration:duration==null?null:Math.max(1,parseInt(duration)||1)});};
    for(const st of catalog.states)remember(st.name,{hidden:st.hidden,remove:false,session:true,duration:st.duration});
    const inspectEffect=effect=>{for(const raw of splitSimpleEffectMarkers(effect)){let m=raw.match(/^!\{Estado:([^}]+)\}$/i);if(m){remember(m[1],{remove:true});continue;}m=raw.match(/^(!)?\{ESTADO:([^}]+)\}$/i);if(m)remember(m[2],{hidden:!!m[1]});}};
    for(const id of book?.order||[]){const sec=book.sections?.[id];if(!sec)continue;for(const st of sec.states||[])if(!st.clear)remember(st.name,{hidden:st.hidden,remove:st.remove});for(const m of sec.mods||[])if(m.kind==='item')inspectEffect(itemMeta(m.item).itemEffect);for(const b of sec.books||[])inspectEffect(itemMeta(b.item).itemEffect);for(const sale of sec.commerce||[])inspectEffect(itemMeta(sale.item).itemEffect);for(const c of sec.choices||[])for(const r of c.requirements||[]){const sm=String(r.item||'').match(/^ESTADO\s*:\s*(.+)$/i);if(sm)remember(sm[1]);}}
    return [...map.values()];
  }
  function customStateMarkerOption(st){const marker=`${st.hidden?'!':''}{ESTADO:${st.name}}`,option=mk(marker,`Estado personalizado${st.duration!=null&&Number.isFinite(Number(st.duration))?` · ${st.duration} turnos`:''}`);if(st.session){option.editType='state';option.editKey=stateKey(st.name);}return option;}
  function customItemMarkerOption(entry){const meta=itemMeta(entry.raw),cat=editorItemCategory(meta),option=mk(editorItemMarker(meta.raw),`${cat.label} personalizado`);if(entry.session){option.editType='item';option.editKey=meta.key;}return option;}
  function mergeMarkerOptions(base,extras){const out=[],used=new Set(),push=option=>{const raw=markerItemRaw(option),key=raw?itemMeta(raw).key:`marker:${markerOptionData(option).marker}`;if(used.has(key))return;used.add(key);out.push(option);};for(const option of extras)push(option);for(const option of base)push(option);return out;}
