    const stateDefs=discoveredEditorialStates(),customStates=stateDefs.map(customStateMarkerOption),customStateRemovals=stateDefs.map(st=>mk(`!{Estado:${st.name}}`,`Remover Estado personalizado: ${st.name}`));
